(function(){
var W=960,H=360;
var draw=SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0,0,W,H);

// ── Data model ──
var n=5;
var edges=[[1,2],[1,5],[2,5],[2,3],[2,4],[3,4],[4,5]];
var edgeMode='idle'; // 'idle','add','remove'
var addFirst=null;
var focusMode='Graph';
var selectedEdge=null;
var selectedVertex=null;

function hasEdge(u,v){for(var i=0;i<edges.length;i++){if((edges[i][0]===u&&edges[i][1]===v)||(edges[i][0]===v&&edges[i][1]===u))return true;}return false;}
function removeEdge(u,v){edges=edges.filter(function(e){return !((e[0]===u&&e[1]===v)||(e[0]===v&&e[1]===u));});}
function addEdge(u,v){if(!hasEdge(u,v))edges.push([u,v]);}

function buildAdjList(){
  var adj={};for(var i=1;i<=n;i++)adj[i]=[];
  for(var i=0;i<edges.length;i++){adj[edges[i][0]].push(edges[i][1]);adj[edges[i][1]].push(edges[i][0]);}
  return adj;
}
function buildMatrix(){
  var m=[];for(var i=0;i<n;i++){m[i]=[];for(var j=0;j<n;j++)m[i][j]=0;}
  for(var i=0;i<edges.length;i++){m[edges[i][0]-1][edges[i][1]-1]=1;m[edges[i][1]-1][edges[i][0]-1]=1;}
  return m;
}

// ── Layout constants ──
var nodePos={1:[80,100],2:[180,100],3:[230,175],4:[180,250],5:[80,250]};
var nodeR=22;

// Panel (b) layout
var listX=270,listCellW=28,listCellH=44,listStartY=40;
var recStartX=310,recW=52,recH=32,recGap=8;

// Panel (c) layout
var matX=660,matY=60,cellS=38;

// ── Colors ──
var ACCENT='#e67e22';
var ACCENT_LIGHT='#fdebd0';
var NODE_FILL='#d5d5d5';
var NODE_STROKE='#333';
var EDGE_STROKE='#333';
var GRID_STROKE='#333';

// ── SVG groups ──
var gGraph=draw.group();
var gList=draw.group();
var gMatrix=draw.group();
var gCaptions=draw.group();
var gHighlight=draw.group();

// ── Draw functions ──
function drawAll(){
  gGraph.clear();gList.clear();gMatrix.clear();gCaptions.clear();gHighlight.clear();
  drawGraphPanel();
  drawListPanel();
  drawMatrixPanel();
  drawCaptions();
}

function drawGraphPanel(){
  // edges
  for(var i=0;i<edges.length;i++){
    var u=edges[i][0],v=edges[i][1];
    var p1=nodePos[u],p2=nodePos[v];
    var line=gGraph.line(p1[0],p1[1],p2[0],p2[1]).stroke({color:EDGE_STROKE,width:1.5});
    line.attr({'data-edge':u+'-'+v});
    line.css('cursor','pointer');
    (function(u,v,el){
      el.on('click',function(){onEdgeClick(u,v);});
      el.on('mousemove',function(e){showTooltip('Edge '+u+'-'+v,e);});
      el.on('mouseleave',function(){hideTooltip();});
    })(u,v,line);
  }
  // nodes
  for(var v=1;v<=n;v++){
    var p=nodePos[v];
    var c=gGraph.circle(nodeR*2).center(p[0],p[1]).fill(NODE_FILL).stroke({color:NODE_STROKE,width:1.5});
    c.attr({'data-node':v});
    c.css('cursor','pointer');
    var t=gGraph.text(String(v)).center(p[0],p[1]).font({size:14,family:'sans-serif',weight:'bold'});
    t.attr({'pointer-events':'none'});
    (function(v,el){
      el.on('click',function(){onNodeClick(v);});
      el.on('mousemove',function(e){showTooltip('Vertex '+v,e);});
      el.on('mouseleave',function(){hideTooltip();});
    })(v,c);
  }
}

function drawListPanel(){
  var adj=buildAdjList();
  for(var v=1;v<=n;v++){
    var y=listStartY+(v-1)*listCellH;
    // index cell
    var cell=gList.rect(listCellW,listCellH-6).move(listX,y).fill('#ccc').stroke({color:'#555',width:1});
    var lbl=gList.text(String(v)).move(listX-16,y+10).font({size:13,family:'sans-serif'});
    // arrow from index to first record
    var chain=adj[v];
    if(chain.length>0){
      gList.line(listX+listCellW,y+(listCellH-6)/2,recStartX-4,y+(listCellH-6)/2)
        .stroke({color:'#333',width:1}).marker('end',makeArrow());
    }
    // records
    for(var j=0;j<chain.length;j++){
      var rx=recStartX+j*(recW+recGap);
      var ry=y;
      var box=gList.rect(recW,recH-6).move(rx,ry).fill('#f0f0f0').stroke({color:'#555',width:1});
      box.attr({'data-rec':v+'-'+chain[j]});
      // divider
      gList.line(rx+recW/2,ry,rx+recW/2,ry+recH-6).stroke({color:'#555',width:1});
      // value
      gList.text(String(chain[j])).center(rx+recW/4,ry+(recH-6)/2).font({size:12,family:'sans-serif'});
      // next pointer
      if(j<chain.length-1){
        gList.line(rx+recW,ry+(recH-6)/2,rx+recW+recGap-4,ry+(recH-6)/2)
          .stroke({color:'#333',width:1}).marker('end',makeArrow());
      } else {
        // null slash
        gList.line(rx+recW/2+4,ry+4,rx+recW-4,ry+recH-10).stroke({color:'#333',width:1.5});
      }
