      el.on('mouseleave',function(){hideTooltip();});
    })(u,v,line);
  }
  // nodes
  for(var v=1;v<=n;v++){
    var p=nodePos[v];
    var c=gGraph.circle(nodeR*2).center(p[0],p[1]).fill(NODE_FILL).stroke({color:NODE_STROKE,width:1.5});
    c.attr({'data-node':v});
    c.css('cursor','pointer');
    var t=gGraph.text(String(v)).center(p[0],p[1]).font({size:14,family:'sans-serif',weight:'bold'});
    t.attr({'pointer-events':'none'});
    (function(v,el){
      el.on('click',function(){onNodeClick(v);});
      el.on('mousemove',function(e){showTooltip('Vertex '+v,e);});
      el.on('mouseleave',function(){hideTooltip();});
    })(v,c);
  }
}

function drawListPanel(){
  var adj=buildAdjList();
  for(var v=1;v<=n;v++){
    var y=listStartY+(v-1)*listCellH;
    // index cell
    var cell=gList.rect(listCellW,listCellH-6).move(listX,y).fill('#ccc').stroke({color:'#555',width:1});
    var lbl=gList.text(String(v)).move(listX-16,y+10).font({size:13,family:'sans-serif'});
    // arrow from index to first record
    var chain=adj[v];
    if(chain.length>0){
      gList.line(listX+listCellW,y+(listCellH-6)/2,recStartX-4,y+(listCellH-6)/2)
        .stroke({color:'#333',width:1}).marker('end',makeArrow());
    }
    // records
    for(var j=0;j<chain.length;j++){
      var rx=recStartX+j*(recW+recGap);
      var ry=y;
      var box=gList.rect(recW,recH-6).move(rx,ry).fill('#f0f0f0').stroke({color:'#555',width:1});
      box.attr({'data-rec':v+'-'+chain[j]});
      // divider
      gList.line(rx+recW/2,ry,rx+recW/2,ry+recH-6).stroke({color:'#555',width:1});
      // value
      gList.text(String(chain[j])).center(rx+recW/4,ry+(recH-6)/2).font({size:12,family:'sans-serif'});
      // next pointer
      if(j<chain.length-1){
        gList.line(rx+recW,ry+(recH-6)/2,rx+recW+recGap-4,ry+(recH-6)/2)
          .stroke({color:'#333',width:1}).marker('end',makeArrow());
      } else {
        // null slash
        gList.line(rx+recW/2+4,ry+4,rx+recW-4,ry+recH-10).stroke({color:'#333',width:1.5});
      }
      // click on record
      (function(v,nb,el){
        el.css('cursor','pointer');
        el.on('click',function(){onRecordClick(v,nb);});
        el.on('mousemove',function(e){showTooltip('Record: '+v+'→'+nb,e);});
        el.on('mouseleave',function(){hideTooltip();});
      })(v,chain[j],box);
    }
  }
}

function drawMatrixPanel(){
  var m=buildMatrix();
  // headers
  for(var j=1;j<=n;j++){
    gMatrix.text(String(j)).center(matX+(j-1)*cellS+cellS/2,matY-12).font({size:13,family:'sans-serif'});
  }
  for(var i=1;i<=n;i++){
    gMatrix.text(String(i)).center(matX-16,matY+(i-1)*cellS+cellS/2).font({size:13,family:'sans-serif'});
  }
  // grid border
  gMatrix.rect(n*cellS,n*cellS).move(matX,matY).fill('none').stroke({color:GRID_STROKE,width:1.5});
  // cells
  for(var i=0;i<n;i++){
    for(var j=0;j<n;j++){
      var cx=matX+j*cellS,cy=matY+i*cellS;
      var cell=gMatrix.rect(cellS,cellS).move(cx,cy).fill('none').stroke({color:'#999',width:0.5});
      cell.attr({'data-cell':(i+1)+'-'+(j+1)});
      var val=gMatrix.text(String(m[i][j])).center(cx+cellS/2,cy+cellS/2).font({size:14,family:'monospace'});
      val.attr({'pointer-events':'none'});
      (function(r,c,el){
        el.css('cursor','pointer');
        el.on('click',function(){onCellClick(r,c);});
        el.on('mousemove',function(e){showTooltip('Matrix['+r+']['+c+'] = '+m[r-1][c-1],e);});
        el.on('mouseleave',function(){hideTooltip();});
      })(i+1,j+1,cell);
    }
  }
}

function drawCaptions(){
  gCaptions.text('(a)').center(140,H-15).font({size:14,family:'serif'});
  gCaptions.text('(b)').center(430,H-15).font({size:14,family:'serif'});
  gCaptions.text('(c)').center(760,H-15).font({size:14,family:'serif'});
}

function makeArrow(){
  var m=draw.marker(8,8,function(add){add.path('M0,0 L8,4 L0,8 Z').fill('#333');});
  return m;
}

// ── Highlight functions ──
function clearHighlights(){
  gHighlight.clear();
  selectedEdge=null;selectedVertex=null;
}

function highlightEdgeInGraph(u,v){
  var p1=nodePos[u],p2=nodePos[v];
  gHighlight.line(p1[0],p1[1],p2[0],p2[1]).stroke({color:ACCENT,width:4}).attr({'pointer-events':'none'});
}

function highlightNodeInGraph(v){
  var p=nodePos[v];
  gHighlight.circle(nodeR*2+6).center(p[0],p[1]).fill('none').stroke({color:ACCENT,width:3}).attr({'pointer-events':'none'});
}

function highlightRecordInList(u,v){
  var adj=buildAdjList();
  var chain=adj[u];
  var idx=chain.indexOf(v);
  if(idx<0)return;
  var y=listStartY+(u-1)*listCellH;
  var rx=recStartX+idx*(recW+recGap);
  gHighlight.rect(recW+2,recH-4).move(rx-1,y-1).fill(ACCENT_LIGHT).stroke({color:ACCENT,width:2}).attr({'pointer-events':'none'});
}

function highlightCellInMatrix(r,c){
  var cx=matX+(c-1)*cellS,cy=matY+(r-1)*cellS;
  gHighlight.rect(cellS,cellS).move(cx,cy).fill(ACCENT_LIGHT).stroke({color:ACCENT,width:2}).attr({'pointer-events':'none'});
}

function highlightEdgeEverywhere(u,v){
  clearHighlights();
  selectedEdge=[u,v];
  highlightEdgeInGraph(u,v);
  highlightRecordInList(u,v);
  highlightRecordInList(v,u);
  highlightCellInMatrix(u,v);
  highlightCellInMatrix(v,u);
}

function highlightVertexEverywhere(v){
  clearHighlights();
  selectedVertex=v;
  highlightNodeInGraph(v);
  var adj=buildAdjList();
  var neighbors=adj[v];
  for(var i=0;i<neighbors.length;i++){
    highlightNodeInGraph(neighbors[i]);
    highlightRecordInList(v,neighbors[i]);
    highlightCellInMatrix(v,neighbors[i]);
    highlightCellInMatrix(neighbors[i],v);
  }
  // highlight the row in matrix
  for(var j=1;j<=n;j++){
    if(buildMatrix()[v-1][j-1]===1){
      highlightCellInMatrix(v,j);
      highlightCellInMatrix(j,v);
    }
  }
}

// ── Interaction handlers ──
function onNodeClick(v){
  if(edgeMode==='add'){
    if(addFirst===null){addFirst=v;highlightNodeInGraph(v);}
    else{
      if(addFirst!==v&&!hasEdge(addFirst,v)){
        addEdge(addFirst,v);
        drawAll();
        highlightEdgeEverywhere(addFirst,v);
      }
      addFirst=null;
    }
    return;
  }
  if(edgeMode==='remove'){return;}
  highlightVertexEverywhere(v);
}

function onEdgeClick(u,v){
  if(edgeMode==='remove'){
    removeEdge(u,v);
    drawAll();
    return;
  }
  highlightEdgeEverywhere(u,v);
}

function onRecordClick(u,v){
  highlightEdgeEverywhere(u,v);
}

function onCellClick(r,c){
  if(r===c)return;
  if(buildMatrix()[r-1][c-1]===1){
    highlightEdgeEverywhere(r,c);
  }
}

// ── UI controls ──
window.setFocus=function(mode){
  focusMode=mode;
  clearHighlights();
};

window.cycleEdgeMode=function(){
  if(edgeMode==='idle')edgeMode='add';
  else if(edgeMode==='add')edgeMode='remove';
  else edgeMode='idle';
  addFirst=null;
  document.getElementById('edgeEditInput').textContent='Edge mode: '+edgeMode;
  clearHighlights();
};

// ── Demo steps ──
var steps=[
  {title:'One graph, three encodings',narration:'The same five-vertex graph appears as a drawing, an adjacency list, and an adjacency matrix. With focus on the graph, pick vertex 2 and watch its neighbors (1, 3, 4, 5) highlight in the list row and the matrix row/column.',
   state:{focus:'Graph',edgeMode:'idle',action:function(){highlightVertexEverywhere(2);}}},
  {title:'An edge is stored twice',narration:'Click edge 2-5 in the drawing (or the 1 at row 2, column 5). The two list records — 5 in row 2\'s chain and 2 in row 5\'s chain — and the symmetric matrix cells (2,5) and (5,2) all light up together.',
   state:{focus:'Adjacency list',edgeMode:'idle',action:function(){highlightEdgeEverywhere(2,5);}}},
  {title:'Same relationships, matrix view',narration:'Switch focus to the matrix. Selecting any vertex now highlights its full row and column, and the symmetry across the diagonal is exactly the list\'s duplicated records seen from another angle.',
   state:{focus:'Adjacency matrix',edgeMode:'idle',action:function(){highlightVertexEverywhere(3);}}},
  {title:'Add an edge',narration:'Choose the non-adjacent pair 1-3 and press add edge. A new line 1-3 appears in the graph, a record 3 is prepended to row 1\'s chain and a record 1 to row 3\'s chain, and matrix cells (1,3) and (3,1) flip from 0 to 1.',
   state:{focus:'Graph',edgeMode:'idle',action:function(){addEdge(1,3);drawAll();highlightEdgeEverywhere(1,3);}}},
  {title:'Remove an edge',narration:'Now remove edge 3-4. The graph line vanishes, the record 4 leaves row 3\'s chain and 3 leaves row 4\'s chain, and matrix cells (3,4) and (4,3) flip back to 0 — one logical change, four physical edits.',
   state:{focus:'Graph',edgeMode:'idle',action:function(){removeEdge(3,4);drawAll();}}
];

var currentStep=0;
// Store original edges for reset
var originalEdges=edges.slice();

window.nextStep=function(){
  if(currentStep<steps.length-1){currentStep++;applyStep(currentStep);}
};
window.prevStep=function(){
  if(currentStep>0){currentStep--;applyStep(currentStep);}
};

function applyStep(idx){
  // Reset to original
  edges=originalEdges.slice();
  // Apply cumulative state changes for steps up to idx
  // Step 3 adds edge 1-3, step 4 removes 3-4
  if(idx>=3){addEdge(1,3);}
  if(idx>=4){removeEdge(3,4);}

  var s=steps[idx];
  focusMode=s.state.focus;
  edgeMode=s.state.edgeMode;
  document.getElementById('representationFocusInput').value=focusMode;
  document.getElementById('edgeEditInput').textContent='Edge mode: '+edgeMode;
  document.getElementById('stepLabel').textContent=(idx+1)+'/'+steps.length;
  document.getElementById('demoNarration').textContent=s.narration;
  drawAll();
  if(s.state.action)s.state.action();
}

// ── Initialize ──
drawAll();
document.getElementById('stepLabel').textContent='1/'+steps.length;
window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A single undirected graph can be stored as a drawing, an adjacency list, or an adjacency matrix, and every undirected edge is recorded twice — as two list records and as two symmetric 1s in the matrix.
KEY INSIGHT (what students should walk away understanding): The three panels are the same graph, and the price of an undirected edge is duplication: it lives as two list records and two symmetric matrix 1s, so any edit must touch both copies.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
