(function(){
"use strict";
var W=960,H=430;
var draw=SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0,0,W,H);
draw.attr('preserveAspectRatio','xMidYMid meet');

// ── Ordered adjacency (matches textbook chains exactly) ──
var INITIAL={1:[2,5],2:[1,5,3,4],3:[2,4],4:[2,5,3],5:[4,1,2]};
var adj=cloneAdj(INITIAL);
function cloneAdj(a){var o={};for(var k in a){o[k]=a[k].slice();}return o;}
var n=5;
var edgeMode='idle';
var addFirst=null;
var focusMode='Graph';

function hasEdge(u,v){return adj[u].indexOf(v)>=0;}
function addEdge(u,v){if(u===v||hasEdge(u,v))return;adj[u].unshift(v);adj[v].unshift(u);}
function removeEdge(u,v){adj[u]=adj[u].filter(function(x){return x!==v;});adj[v]=adj[v].filter(function(x){return x!==u;});}
function buildMatrix(){var m=[];for(var i=0;i<n;i++){m[i]=[];for(var j=0;j<n;j++)m[i][j]=0;}for(var u=1;u<=n;u++){for(var t=0;t<adj[u].length;t++){m[u-1][adj[u][t]-1]=1;}}return m;}

// ── Layout ──
var nodePos={1:[70,120],2:[195,120],3:[255,215],4:[195,310],5:[70,310]};
var nodeR=24;
var listX=330,listCellW=30,listCellH=52,listStartY=70;
var recStartX=382,recW=58,recH=40,recGap=12;
var matX=705,matY=95,cellS=48;

var ACCENT='#e67e22',ACCENT_LIGHT='#fdebd0';
var NODE_FILL='#d8d8d8',NODE_STROKE='#222',EDGE_STROKE='#222',GRID_STROKE='#222';

var gGraph=draw.group(),gList=draw.group(),gMatrix=draw.group(),gCaptions=draw.group(),gHighlight=draw.group();

var arrowMarker=draw.marker(10,10,function(add){add.path('M0,0 L10,5 L0,10 Z').fill('#222');});

function drawAll(){
  gGraph.clear();gList.clear();gMatrix.clear();gCaptions.clear();gHighlight.clear();
  drawGraphPanel();drawListPanel();drawMatrixPanel();drawCaptions();applyFocusOpacity(true);
}

function drawGraphPanel(){
  for(var u=1;u<=n;u++){for(var t=0;t<adj[u].length;t++){var v=adj[u][t];if(u<v){
    var p1=nodePos[u],p2=nodePos[v];
    var line=gGraph.line(p1[0],p1[1],p2[0],p2[1]).stroke({color:EDGE_STROKE,width:1.6});
    line.css('cursor','pointer');
    (function(u,v,el){el.on('click',function(){onEdgeClick(u,v);});el.on('mousemove',function(e){showTooltip('Edge '+u+'–'+v,e);});el.on('mouseleave',hideTooltip);})(u,v,line);
  }}}
  for(var v=1;v<=n;v++){
    var p=nodePos[v];
    var c=gGraph.circle(nodeR*2).center(p[0],p[1]).fill(NODE_FILL).stroke({color:NODE_STROKE,width:1.6});
    c.css('cursor','pointer');
    gGraph.text(String(v)).center(p[0],p[1]).font({size:18,family:'sans-serif',weight:'bold'}).attr({'pointer-events':'none'});
    (function(v,el){el.on('click',function(){onNodeClick(v);});el.on('mousemove',function(e){showTooltip('Vertex '+v,e);});el.on('mouseleave',hideTooltip);})(v,c);
  }
}

function drawListPanel(){
  for(var v=1;v<=n;v++){
    var y=listStartY+(v-1)*listCellH;
    gList.text(String(v)).center(listX-14,y+listCellH/2-4).font({size:16,family:'sans-serif'});
    gList.rect(listCellW,listCellH-8).move(listX,y).fill('#cfcfcf').stroke({color:'#555',width:1});
    var chain=adj[v];
    if(chain.length>0){
      gList.line(listX+listCellW,y+(listCellH-8)/2,recStartX-5,y+(listCellH-8)/2).stroke({color:'#222',width:1.2}).marker('end',arrowMarker);
    }
    for(var j=0;j<chain.length;j++){
      var rx=recStartX+j*(recW+recGap),ry=y;
      var box=gList.rect(recW,recH).move(rx,ry).fill('#f2f2f2').stroke({color:'#555',width:1});
      var divX=rx+recW*0.55;
      gList.line(divX,ry,divX,ry+recH).stroke({color:'#555',width:1});
      gList.text(String(chain[j])).center(rx+recW*0.275,ry+recH/2).font({size:16,family:'sans-serif'});
      if(j<chain.length-1){
        gList.line(divX+4,ry+recH/2,rx+recW+recGap-5,ry+recH/2).stroke({color:'#222',width:1.2}).marker('end',arrowMarker);
      }else{
        gList.line(divX+6,ry+6,rx+recW-6,ry+recH-6).stroke({color:'#222',width:1.6});
      }
      (function(v,nb,el){el.css('cursor','pointer');el.on('click',function(){onRecordClick(v,nb);});el.on('mousemove',function(e){showTooltip('Record '+v+' → '+nb,e);});el.on('mouseleave',hideTooltip);})(v,chain[j],box);
    }
  }
}

function drawMatrixPanel(){
  var m=buildMatrix();
  for(var j=1;j<=n;j++){gMatrix.text(String(j)).center(matX+(j-1)*cellS+cellS/2,matY-16).font({size:16,family:'sans-serif'});}
  for(var i=1;i<=n;i++){gMatrix.text(String(i)).center(matX-18,matY+(i-1)*cellS+cellS/2).font({size:16,family:'sans-serif'});}
  gMatrix.rect(n*cellS,n*cellS).move(matX,matY).fill('none').stroke({color:GRID_STROKE,width:1.6});
  for(var r=0;r<n;r++){for(var c=0;c<n;c++){
    var cx=matX+c*cellS,cy=matY+r*cellS;
    var cell=gMatrix.rect(cellS,cellS).move(cx,cy).fill('none').stroke({color:'#999',width:0.5});
    cell.css('cursor','pointer');
    gMatrix.text(String(m[r][c])).center(cx+cellS/2,cy+cellS/2).font({size:18,family:'monospace'}).attr({'pointer-events':'none'});
    (function(rr,cc,el){el.on('click',function(){onCellClick(rr,cc);});el.on('mousemove',function(e){showTooltip('Matrix['+rr+']['+cc+'] = '+m[rr-1][cc-1],e);});el.on('mouseleave',hideTooltip);})(r+1,c+1,cell);
  }}
}

function drawCaptions(){
  gCaptions.text('(a)').center(150,H-12).font({size:16,family:'serif'});
  gCaptions.text('(b)').center(470,H-12).font({size:16,family:'serif'});
  gCaptions.text('(c)').center(820,H-12).font({size:16,family:'serif'});
}

// ── Highlights ──
function clearHighlights(){gHighlight.clear();}
function hlEdgeGraph(u,v){var p1=nodePos[u],p2=nodePos[v];gHighlight.line(p1[0],p1[1],p2[0],p2[1]).stroke({color:ACCENT,width:5}).attr({'pointer-events':'none'});}
function hlNodeGraph(v){var p=nodePos[v];gHighlight.circle(nodeR*2+8).center(p[0],p[1]).fill('none').stroke({color:ACCENT,width:3}).attr({'pointer-events':'none'});}
function hlRecord(u,v){var idx=adj[u].indexOf(v);if(idx<0)return;var y=listStartY+(u-1)*listCellH;var rx=recStartX+idx*(recW+recGap);gHighlight.rect(recW+2,recH+2).move(rx-1,y-1).fill(ACCENT_LIGHT).stroke({color:ACCENT,width:2}).attr({'pointer-events':'none'});}
function hlCell(r,c){var cx=matX+(c-1)*cellS,cy=matY+(r-1)*cellS;gHighlight.rect(cellS,cellS).move(cx,cy).fill(ACCENT_LIGHT).stroke({color:ACCENT,width:2}).attr({'pointer-events':'none'});}
function highlightEdgeEverywhere(u,v){clearHighlights();hlEdgeGraph(u,v);hlRecord(u,v);hlRecord(v,u);hlCell(u,v);hlCell(v,u);}
function highlightVertexEverywhere(v){clearHighlights();hlNodeGraph(v);var nb=adj[v];for(var i=0;i<nb.length;i++){hlNodeGraph(nb[i]);hlRecord(v,nb[i]);hlCell(v,nb[i]);hlCell(nb[i],v);}}

// ── Interaction ──
function onNodeClick(v){
  if(edgeMode==='add'){
    if(addFirst===null){addFirst=v;clearHighlights();hlNodeGraph(v);}
    else{if(addFirst!==v){addEdge(addFirst,v);drawAll();highlightEdgeEverywhere(addFirst,v);}addFirst=null;}
    return;
  }
  if(edgeMode==='remove')return;
  highlightVertexEverywhere(v);
}
function onEdgeClick(u,v){
  if(edgeMode==='remove'){removeEdge(u,v);drawAll();return;}
  highlightEdgeEverywhere(u,v);
}
function onRecordClick(u,v){highlightEdgeEverywhere(u,v);}
function onCellClick(r,c){if(r===c)return;if(buildMatrix()[r-1][c-1]===1)highlightEdgeEverywhere(r,c);}

// ── Focus (real visual change: dim non-focused panels) ──
function applyFocusOpacity(instant){
  var oG=1,oL=1,oM=1;
  if(focusMode==='Adjacency list'){oG=0.28;oM=0.28;}
  else if(focusMode==='Adjacency matrix'){oG=0.28;oL=0.28;}
  if(instant){gGraph.opacity(oG);gList.opacity(oL);gMatrix.opacity(oM);}
  else{gGraph.animate(250).opacity(oG);gList.animate(250).opacity(oL);gMatrix.animate(250).opacity(oM);}
}
window.setFocus=function(mode){focusMode=mode;clearHighlights();applyFocusOpacity(false);};

window.cycleEdgeMode=function(){
  if(edgeMode==='idle')edgeMode='add';
  else if(edgeMode==='add')edgeMode='remove';
  else edgeMode='idle';
  addFirst=null;clearHighlights();
  document.getElementById('edgeEditInput').textContent='Edge mode: '+edgeMode;
